import java.util.*; public class Q15_PassportCitizen{static class Passport{String n,i,e;Passport(String n,String i,String e){this.n=n;this.i=i;this.e=e;}public String toString(){return "Passport: "+n+" Issue: "+i+" Expiry: "+e;}}static class Citizen{String n,d,a;Passport p;Citizen(String n,String d,String a){this.n=n;this.d=d;this.a=a;}public String toString(){return "Citizen: "+n+" DOB: "+d+" Address: "+a+"\n"+p;}}public static void main(String[]x){Scanner s=new Scanner(System.in);String[]c=s.nextLine().split(",",3),p=s.nextLine().split(",",3);Citizen z=new Citizen(c[0],c[1],c[2]);z.p=new Passport(p[0],p[1],p[2]);System.out.println(z);}}
